package com.coverswap.cloth;
import android.app.*;import android.os.*;import android.content.*;import android.net.*;import android.graphics.*;import android.widget.*;import android.util.Base64;
import org.json.*;import java.io.*;import java.net.*;import java.util.concurrent.*;
public class MainActivity extends Activity {
 final ExecutorService pool=Executors.newSingleThreadExecutor();EditText url;Spinner person,category;ImageView preview;TextView status;Button photo,garment,detect,swap,save;CheckBox high;EditText steps,seed;String image,clothes;Bitmap result;boolean busy=false;
 public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(20,20,20,20);setContentView(root);
 TextView title=new TextView(this);title.setText("CoverSwap • Clothes");title.setTextSize(25);root.addView(title);
 url=new EditText(this);url.setSingleLine(true);url.setHint("Server URL");url.setText(getPreferences(0).getString("url","http://10.0.2.2:8000"));root.addView(url);
 photo=button(root,"1. Choose person photo",()->choose(1));garment=button(root,"2. Choose garment photo",()->choose(2));
 detect=button(root,"3. Detect people",()->request(false));person=new Spinner(this);root.addView(person);category=new Spinner(this);category.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"upper_body","lower_body","dress"}));root.addView(category);
 steps=new EditText(this);steps.setInputType(2);steps.setHint("Steps (1–60)");steps.setText("30");root.addView(steps);seed=new EditText(this);seed.setInputType(2);seed.setHint("Seed");seed.setText("42");root.addView(seed);high=new CheckBox(this);high.setText("High resolution (768 × 1024)");root.addView(high);
 swap=button(root,"4. Swap clothes",()->request(true));preview=new ImageView(this);preview.setScaleType(ImageView.ScaleType.FIT_CENTER);root.addView(preview,new LinearLayout.LayoutParams(-1,0,1));save=button(root,"Save result",()->{if(result==null)return;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("image/png");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"clothswap.png");startActivityForResult(i,3);});status=new TextView(this);root.addView(status);status.setText("Select two photos. AI runs on your configured server.");}
 Button button(LinearLayout root,String label,Runnable r){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setOnClickListener(v->r.run());root.addView(b);return b;}
 void choose(int code){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,code);}
 void state(boolean b){busy=b;for(Button v:new Button[]{photo,garment,detect,swap,save})v.setEnabled(!b);url.setEnabled(!b);person.setEnabled(!b);}
 void error(Exception e){runOnUiThread(()->{state(false);status.setText(e.getMessage());});}
 protected void onActivityResult(int code,int rc,Intent data){super.onActivityResult(code,rc,data);if(rc!=RESULT_OK||data==null)return;Uri uri=data.getData();if(uri==null)return;state(true);pool.execute(()->{try{
 if(code==3){try(OutputStream out=getContentResolver().openOutputStream(uri)){if(!result.compress(Bitmap.CompressFormat.PNG,100,out))throw new IOException("Save failed");}runOnUiThread(()->{state(false);status.setText("Saved");});return;}
 byte[] raw;try(InputStream in=getContentResolver().openInputStream(uri)){raw=read(in,12000000);}String b64=Base64.encodeToString(raw,Base64.NO_WRAP);if(code==1)image=b64;else clothes=b64;
 Bitmap bitmap=BitmapFactory.decodeByteArray(raw,0,raw.length);runOnUiThread(()->{if(code==1){person.setAdapter(null);result=null;}preview.setImageBitmap(bitmap);state(false);status.setText(code==1?"Photo loaded; detect people next":"Garment loaded");});}catch(Exception e){error(e);}});}
 static byte[] read(InputStream in,int limit)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new IOException("Image/response too large");out.write(b,0,n);}return out.toByteArray();}
 void request(boolean generate){try{
 if(image==null||generate&&clothes==null)throw new Exception("Choose the required photos first");if(generate&&person.getSelectedItemPosition()<0)throw new Exception("Detect and select a person first");
 String base=url.getText().toString().trim().replaceAll("/+$","");if(!base.startsWith("http://")&&!base.startsWith("https://"))throw new Exception("Enter an HTTP or HTTPS server URL");getPreferences(0).edit().putString("url",base).apply();JSONObject req=new JSONObject().put("photo",image);
 if(generate)req.put("garment",clothes).put("person",person.getSelectedItemPosition()).put("category",category.getSelectedItem()).put("steps",Integer.parseInt(steps.getText().toString())).put("seed",Integer.parseInt(seed.getText().toString())).put("high_resolution",high.isChecked());
 state(true);status.setText(generate?"Generating on server… this may take several minutes":"Detecting people…");pool.execute(()->{HttpURLConnection conn=null;try{conn=(HttpURLConnection)new URL(base+(generate?"/swap":"/detect")).openConnection();conn.setConnectTimeout(15000);conn.setReadTimeout(900000);conn.setRequestMethod("POST");conn.setDoOutput(true);conn.setRequestProperty("Content-Type","application/json");byte[] body=req.toString().getBytes("UTF-8");conn.setFixedLengthStreamingMode(body.length);try(OutputStream out=conn.getOutputStream()){out.write(body);}int code=conn.getResponseCode();String response;try(InputStream in=code<400?conn.getInputStream():conn.getErrorStream()){response=new String(read(in,90000000),"UTF-8");}if(code>=400)throw new IOException("Server "+code+": "+response);JSONObject obj=new JSONObject(response);
 if(generate){byte[] bytes=Base64.decode(obj.getString("image"),Base64.DEFAULT);Bitmap b=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(b==null)throw new IOException("Invalid server image");result=b;runOnUiThread(()->preview.setImageBitmap(b));}else{JSONArray people=obj.getJSONArray("people");String[] labels=new String[people.length()];for(int j=0;j<labels.length;j++)labels[j]=people.getJSONObject(j).getString("label")+"  "+people.getJSONObject(j).getJSONArray("box");runOnUiThread(()->person.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,labels)));}
 runOnUiThread(()->{state(false);status.setText(generate?"Done. Save the result.":"Select a person from the list, then swap.");});}catch(Exception e){error(e);}finally{if(conn!=null)conn.disconnect();}});
 }catch(Exception e){error(e);}}
 protected void onDestroy(){pool.shutdown();super.onDestroy();}
}
